let successCount = Number(pm.environment.get("tc44_success_count") || 0);
let failureCount = Number(pm.environment.get("tc44_failure_count") || 0);

let responseTimes = JSON.parse(
    pm.environment.get("tc44_response_times") || "[]"
);

let requestPassed = true;

// Helper function for assertions
function check(condition, message) {
    pm.test(message, function () {
        pm.expect(condition).to.eql(true);
    });

    if (!condition) {
        requestPassed = false;
    }
}

// 1. Check HTTP status
check(
    pm.response.code === 200,
    `Request ${runCount}: status is 200`
);

// 2. Check response time
check(
    pm.response.responseTime <= 2000,
    `Request ${runCount}: response time is <= 1000 ms`
);

// 3. Parse JSON response
let tc44Data = [];

try {
    tc44Data = pm.response.json();

    check(
        Array.isArray(tc44Data),
        `Request ${runCount}: valid JSON array`
    );

} catch (error) {
    check(false, `Request ${runCount}: valid JSON array`);
}

// 4. Check that records are returned
if (Array.isArray(tc44Data)) {

    check(
        tc44Data.length > 0,
        `Request ${runCount}: records are returned`
    );

    // 5. Check required fields
    check(
        tc44Data.every(record =>
            record.id !== undefined &&
            record.user_id !== undefined &&
            record.test_data !== undefined
        ),
        `Request ${runCount}: all records have required fields`
    );
}

